import {escapeHtml as e} from '../shared/utils.js?v=0.15.0';
import {attachCardDrag} from '../shared/drag.js?v=0.15.0';
import {validateSession} from '../creative-kit/state.js?v=0.15.0';
import {validate as validateTerritory,markdown as territoryMarkdown} from '../territory/state.js?v=0.15.0';
import {uid} from './model.js?v=0.15.0';
import {VERDICTS,axes,cell,selectedCell,locationOf,gap,noteKey,labelCoordinates,usedOption,transition} from './map.js?v=0.15.0';
import {fromTerritory} from './import.js?v=0.15.0';

const labels=items=>items.map(i=>`${i.dimension}: ${i.label}`).join(' · ');
const name=(w,c)=>c.title||`Combination ${w.concepts.indexOf(c)+1}`;
export const navigation=w=>`<nav class="view-nav" aria-label="Ways to explore"><button class="btn ${w.view==='generate'?'primary':''}" data-map-action="view" data-id="generate" aria-pressed="${w.view==='generate'}">Combine ingredients</button><button class="btn ${w.view==='map'?'primary':''}" data-map-action="view" data-id="map" aria-pressed="${w.view==='map'}">Map coverage</button><span>One collection · ${w.concepts.length} concepts</span><button class="btn quiet" data-map-action="earlier">Bring Territory work</button></nav>`;
export const sourceRecord=w=>w.source?`<details class="source-record"><summary>Original Territory workspace · unchanged source</summary><p>The original is still saved in Territory. This copy keeps every source field in its JSON export.</p><pre>${e(territoryMarkdown(w.source.workspace))}</pre></details>`:'';
function idea(w,c){return `<article class="map-idea" data-drag-id="${e(c.id)}"><div class="map-idea-top"><button class="idea-title" data-map-action="develop" data-id="${e(c.id)}">${e(name(w,c))}</button><button class="drag-handle" data-drag-handle data-map-action="move" data-id="${e(c.id)}" aria-label="Move ${e(name(w,c))}" title="Drag to another cell, or click to choose">⠿</button></div>${c.mechanism?`<p>${e(c.mechanism)}</p>`:''}${c.ancestry.parked?'<small class="parked-label">Parked</small>':''}${c.fitNeedsReview?'<small class="fit-warning">Review fit</small>':''}</article>`;}
export function mapView(w){
 const [r,c]=axes(w),key=selectedCell(w),g=gap(w),unplaced=w.concepts.filter(i=>locationOf(w,i)==='unplaced');
 const options=(selected,other)=>w.dimensions.map(d=>`<option value="${e(d.id)}" ${d.id===selected?'selected':''} ${d.id===other?'disabled':''}>${e(d.name)}</option>`).join('');
 return `<section class="coverage"><div class="step-heading"><div><h2>Where have you looked?</h2><p>Move a concept to question its fit. Empty space may have a good reason to stay empty.</p></div><button class="btn" data-action="add-axis" ${w.dimensions.length>=8?'disabled':''}>+ Dimension</button></div>
 <div class="map-controls"><label>Rows<select id="map-rows">${options(r.id,c.id)}</select></label><button class="btn quiet" data-action="edit-axis" data-id="${e(r.id)}">Edit rows</button><label>Columns<select id="map-columns">${options(c.id,r.id)}</select></label><button class="btn quiet" data-action="edit-axis" data-id="${e(c.id)}">Edit columns</button><button class="btn quiet" data-map-action="transpose">Swap axes</button></div>
 <p class="map-hint">Scroll sideways for more columns ↔ · Drag a handle or click it to move. Counts show coverage, not quality.</p>
 <div class="map-scroll" tabindex="0" role="region" aria-label="Concept coverage map; scroll horizontally"><table class="coverage-table"><thead><tr><th scope="col">Rows ↓<br>Columns →</th>${c.options.map(o=>`<th scope="col">${e(o.label)}</th>`).join('')}</tr></thead><tbody>${r.options.map(row=>`<tr><th scope="row">${e(row.label)}</th>${c.options.map(col=>{const k=cell(row.id,col.id),ideas=w.concepts.filter(i=>locationOf(w,i)===k),n=gap(w,k);return `<td data-drop-id="${e(k)}" class="${k===key?'selected-cell':''}"><div class="cell-tools"><span>${ideas.length} ${ideas.length===1?'concept':'concepts'}</span><button class="btn small quiet" data-map-action="cell" data-id="${e(k)}" aria-label="Inspect ${e(row.label)} × ${e(col.label)}" aria-pressed="${k===key}">Inspect</button></div>${n.verdict!=='open'?`<p class="gap-verdict">${VERDICTS[n.verdict]}</p>`:''}${ideas.map(i=>idea(w,i)).join('')}${!ideas.length?'<p class="empty-cell">Unoccupied</p>':''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>
 <section class="unplaced" data-drop-id="unplaced" aria-label="Unplaced concepts"><h3>Not placed on both axes <span>${unplaced.length}</span></h3><p>Partial classifications stay intact until you move the concept. Other dimensions keep their own placements.</p><div class="unplaced-ideas">${unplaced.map(i=>idea(w,i)).join('')}</div></section>
 <section class="gap-notebook" id="gap-notebook"><p class="eyebrow">Inspect this space · ${w.concepts.filter(i=>locationOf(w,i)===key).length} concepts</p><h3>${e(labels(labelCoordinates(w,g.coordinates)))}</h3><div class="gap-fields"><label>Your reading<select id="gap-verdict">${Object.entries(VERDICTS).map(([v,label])=>`<option value="${v}" ${g.verdict===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Why is it like this?<textarea id="gap-reason" maxlength="20000" placeholder="An assumption we have not tested, a real limit, or simply somewhere we have not looked…">${e(g.reason)}</textarea></label></div><div class="gap-actions"><button class="btn primary" data-map-action="capture-gap">Develop a candidate here</button><button class="btn" data-map-action="mix-gap">Lock these two ingredients</button><button class="btn quiet" data-map-action="clear-gap">Clear note</button></div><p class="muted">A candidate keeps this note as its starting context. Locking returns to the mixer; your other locks stay as they are.</p></section>
 <details class="all-gaps"><summary>All examined spaces · ${Object.keys(w.map.notes).length}</summary><div class="gap-list">${gapList(w)}</div></details></section>`;
}
function gapList(w){return `<p>Notes follow their dimensions when you switch or rename axes.</p>${Object.entries(w.map.notes).map(([id,g])=>`<article><button class="btn quiet" data-map-action="open-gap" data-id="${e(id)}">${e(labels(labelCoordinates(w,g.coordinates)))}</button><p>${VERDICTS[g.verdict]}${g.reason?' · '+e(g.reason):''}</p></article>`).join('')}`;}
export function fitEditor(w,c){
 const placement=w.dimensions.map(d=>({dimension:d.name,label:d.options.find(o=>o.id===c.placement[d.id])?.label??'Unplaced'}));
 return `${c.origin?`<details class="gap-origin"><summary>Gap that prompted this concept</summary><p>${e(labels(c.origin.ingredients))}</p><p>${VERDICTS[c.origin.verdict]} · ${e(c.origin.reason||'No reason recorded at capture.')}</p></details>`:''}<details class="fit-details" ${c.fitNeedsReview?'open':''}><summary>Current map fit${c.fitNeedsReview?' · needs review':''}</summary><p>${e(labels(placement))}</p><label>What makes this placement plausible?<textarea data-field="fit" maxlength="20000" placeholder="Does the mechanism still serve this person or need? What would have to change?">${e(c.fit)}</textarea></label><div class="gap-actions"><button class="btn" data-map-action="move" data-id="${e(c.id)}">Move on current map</button>${c.fitNeedsReview?`<button class="btn" data-map-action="review-fit" data-id="${e(c.id)}">I have reviewed the fit</button>`:''}</div><p class="muted">Moving or renaming a mapped ingredient asks you to review this fit. It keeps your written idea and original ingredients.</p></details>`;
}

export function wireCoverage({app,dialog,current,change,openDialog,addWorkspace,render,save,toast,checkpoint}){
 const send=a=>change(w=>Object.assign(w,transition(w,a)));
 const develop=()=>{document.querySelector('.concept-editor')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#concept-title')?.focus({preventScroll:true});};
 function earlier(){let workspaces=[],error='';try{const raw=localStorage.getItem('thinking-lab:territory:v1');if(raw)workspaces=validateSession(JSON.parse(raw),validateTerritory).workspaces;}catch{error='Earlier saved work could not be read. It has been left untouched; try importing a Territory JSON export.';}
  openDialog(`<h2>Bring Territory into the Mixer</h2><p>Copy a saved map into a new workspace. Needs and mechanisms become dimensions; ideas, partial placements and gap notes come with it.</p>${error?`<p class="dialog-error">${e(error)}</p>`:''}<div class="preset-grid">${workspaces.map((w,i)=>`<button class="preset-choice" data-copy-territory="${i}"><strong>${e(w.problem||'Untitled Territory workspace')}</strong><span>${w.ideas.length} ideas · ${Object.keys(w.gaps).length} gap notes</span></button>`).join('')||'<p>No saved Territory workspaces found in this browser.</p>'}</div><p>Original work stays in <a href="../territory/">Territory</a>. Its unchanged source record accompanies the copy.</p><div class="actions"><button class="btn" data-action="import">Import Mixer or Territory JSON</button><button class="btn" data-action="close">Close</button></div>`);
  for(const b of dialog.querySelectorAll('[data-copy-territory]'))b.onclick=()=>{try{addWorkspace(fromTerritory(workspaces[Number(b.dataset.copyTerritory)]));toast('Copied into a new workspace. Original Territory work is unchanged.');}catch(error){toast(error.message);}};
 }
 function move(id){const w=current(),[r,c]=axes(w),concept=w.concepts.find(i=>i.id===id),loc=locationOf(w,concept);openDialog(`<form id="move-form"><h2>Place this concept</h2><p>${e(name(w,concept))}</p><label>Where on ${e(r.name)} × ${e(c.name)}?<select name="cell"><option value="unplaced" ${loc==='unplaced'?'selected':''}>Not placed on both axes</option>${r.options.flatMap(row=>c.options.map(col=>`<option value="${e(cell(row.id,col.id))}" ${loc===cell(row.id,col.id)?'selected':''}>${e(row.label)} × ${e(col.label)}</option>`)).join('')}</select></label><p>Changing this classification asks for a fit review. Other dimensions keep their placements.</p><div class="actions"><button class="btn" type="button" data-action="close">Cancel</button><button class="btn primary">Move concept</button></div></form>`);dialog.querySelector('form').onsubmit=event=>{event.preventDefault();try{const selected=event.currentTarget.elements.cell.value;if(selected!==loc)send({type:'move',id,cell:selected});dialog.close();toast('Placement saved. Review whether the mechanism still fits.');}catch(error){toast(error.message);}};}
 document.addEventListener('click',event=>{const b=event.target.closest('[data-map-action]');if(!b||b.disabled)return;const w=current(),id=b.dataset.id;try{switch(b.dataset.mapAction){
  case 'view':send({type:'view',view:id});break;
  case 'earlier':earlier();break;
  case 'cell':send({type:'select-cell',cell:id});document.querySelector('#gap-notebook').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#gap-verdict').focus({preventScroll:true});break;
  case 'open-gap':{const[a,b]=w.map.notes[id].coordinates;change(w=>{w.map.rowId=a.dimensionId;w.map.columnId=b.dimensionId;w.map.row=a.optionId;w.map.column=b.optionId;});document.querySelector('#gap-notebook').scrollIntoView({behavior:'smooth',block:'center'});break;}
  case 'transpose':change(w=>{[w.map.rowId,w.map.columnId]=[w.map.columnId,w.map.rowId];[w.map.row,w.map.column]=[w.map.column,w.map.row];});break;
  case 'clear-gap':send({type:'clear-gap'});toast('Note cleared. Undo brings it back.');break;
  case 'mix-gap':send({type:'mix-gap'});toast('These two ingredients are locked. Mix the others or unlock any ingredient.');break;
  case 'capture-gap':send({type:'capture-gap'});develop();break;
  case 'develop':w.activeConceptId=id;render();develop();break;
  case 'move':move(id);break;
  case 'review-fit':send({type:'review-fit',id});break;
 }}catch(error){toast(error.message);}});
 app.addEventListener('change',event=>{const t=event.target;try{if(t.id==='map-rows'||t.id==='map-columns')send({type:'axes',row:document.querySelector('#map-rows').value,column:document.querySelector('#map-columns').value});else if(t.id==='gap-verdict')send({type:'gap',field:'verdict',value:t.value});}catch(error){toast(error.message);}});
 // Do not rerender while writing. Refresh summaries when they are opened.
 app.addEventListener('toggle',event=>{if(event.target.matches('.all-gaps')&&event.target.open){event.target.querySelector('.gap-list').innerHTML=gapList(current());event.target.querySelector('summary').textContent=`All examined spaces · ${Object.keys(current().map.notes).length}`;}},true);
 attachCardDrag({root:app,onDrop:({itemId,dropId})=>{try{send({type:'move',id:itemId,cell:dropId});toast('Moved. Review whether the idea still fits this space.');}catch(error){toast(error.message);}}});
 return {axisDialog(id){
  const w=current(),d=w.dimensions.find(x=>x.id===id),dimensionId=d?.id??uid();
  const row=o=>`<div class="option-edit" data-option="${e(o.id)}"><label>Option<textarea maxlength="20000" required>${e(o.label)}</textarea></label><button type="button" class="btn quiet" data-remove-option ${d&&usedOption(w,d.id,o.id)?'disabled title="Mapped concepts or gap notes use this option."':''}>Remove</button></div>`;
  const used=d?.options.some(o=>usedOption(w,d.id,o.id));
  openDialog(`<form id="axis-form"><h2>${d?'Edit dimension':'Add a dimension'}</h2><p>Renaming keeps coordinates and notes together. Original concept ingredients stay as captured.</p><label>Dimension name<input name="name" maxlength="20000" required value="${e(d?.name??'')}"></label><div class="option-edits">${(d?.options??[{id:uid(),label:''}]).map(row).join('')}</div><button class="btn" type="button" id="add-option">+ Option</button><p class="muted">Options used by mapped concepts or gap notes cannot be removed. Move those concepts and clear the note first.</p><p class="dialog-error" hidden></p><div class="actions">${d?`<button type="button" class="btn danger" id="remove-dimension" ${w.dimensions.length<=2||used?'disabled':''}>Remove dimension</button>`:''}<button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save dimension</button></div></form>`);
  const form=dialog.querySelector('form'),rows=dialog.querySelector('.option-edits');
  dialog.querySelector('#add-option').onclick=()=>{if(rows.children.length>=12){toast('Keep at most 12 options.');return;}rows.insertAdjacentHTML('beforeend',row({id:uid(),label:''}));rows.lastElementChild.querySelector('textarea').focus();};
  rows.onclick=event=>{const b=event.target.closest('[data-remove-option]');if(b&&!b.disabled){if(rows.children.length<2){toast('Keep at least one option.');return;}b.closest('.option-edit').remove();}};
  const remove=dialog.querySelector('#remove-dimension');if(remove)remove.onclick=()=>{try{send({type:'remove-dimension',id});dialog.close();toast('Dimension removed. Undo brings it back.');}catch(error){toast(error.message);}};
  form.onsubmit=event=>{event.preventDefault();try{
   const options=[...rows.children].map(el=>({id:el.dataset.option,label:el.querySelector('textarea').value}));
   send({type:'dimension',dimension:{id:dimensionId,name:form.elements.name.value,options,selectedId:d?.selectedId??options[0].id,locked:d?.locked??false}});dialog.close();toast('Dimension updated. Changed labels ask for a fit review.');
  }catch(error){const el=dialog.querySelector('.dialog-error');el.textContent=error.message;el.hidden=false;}};
 }};
}
